import { test } from "node:test";
import assert from "node:assert/strict";
import { PLAN_WEIGHT, weightFor, shareOf } from "../src/fairshare.ts";
import { concurrencyFor } from "../src/contracts.ts";
import { queueDepth } from "../src/metrics.ts";

test("weights come from the plan", () => {
  assert.equal(weightFor("acme", [{ org: "acme", plan: "team" }]), PLAN_WEIGHT.team);
});

test("unknown orgs get the default concurrency", () => {
  assert.equal(concurrencyFor("someone-new"), 4);
});

test("queue depth is one gauge per org", () => {
  assert.equal(queueDepth({ a: 1, b: 2 }).length, 2);
});

test("shareOf returns fractional shares for small weights", () => {
  const freeWeight = PLAN_WEIGHT.free;
  const totalWeight = 60 * PLAN_WEIGHT.team;
  const fleet = 240;
  const share = shareOf(freeWeight, totalWeight, fleet);
  assert.ok(share > 0, "free plan should get a fractional share, not zero");
  assert.ok(share < 1, "share should be fractional");
  assert.equal(share, (freeWeight * fleet) / totalWeight);
});

